from sage.all_cmdline import *   # import sage library

_sage_const_20260726 = Integer(20260726); _sage_const_2 = Integer(2); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_1 = Integer(1); _sage_const_1en12 = RealNumber('1e-12'); _sage_const_0 = Integer(0); _sage_const_1en6 = RealNumber('1e-6')# <tensor_anticommutation_from_single_site>: 1 サイトだけ反可換ならテンソル積全体が反交換
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in dir() else "."
load(os.path.join(_dir, "../../_shared/operators.sage"))
import numpy as np
rng = np.random.default_rng(int(_sage_const_20260726 ))
rep = CheckReport("tensor_anticommutation_from_single_site")

def rand2():
    return rng.normal(size=(_sage_const_2 ,_sage_const_2 )) + _sage_const_1j *rng.normal(size=(_sage_const_2 ,_sage_const_2 ))

for M in [_sage_const_2 ,_sage_const_3 ,_sage_const_4 ]:
    for j in range(_sage_const_1 , M+_sage_const_1 ):
        for trial in range(_sage_const_3 ):
            # 第 j サイト: 反可換な組（sigma^x と sigma^z のスカラー倍は反可換）
            a = rng.normal() + _sage_const_1j *rng.normal()
            b = rng.normal() + _sage_const_1j *rng.normal()
            xj, yj = a*SX, b*SZ
            assert np.max(np.abs(yj@xj + xj@yj)) < _sage_const_1en12 
            # 他サイト: 可換な組（片方をスカラー行列にすれば必ず可換）
            xs, ys = [], []
            for k in range(_sage_const_1 , M+_sage_const_1 ):
                if k == j:
                    xs.append(xj); ys.append(yj)
                else:
                    c = rng.normal() + _sage_const_1j *rng.normal()
                    xs.append(rand2()); ys.append(c*I2)
            X = kron_list(xs); Y = kron_list(ys)
            rep.close(acomm(X, Y), np.zeros_like(X), f"M={M} j={j} t={trial}: [X,Y]+ = 0")

# 仮定を崩す: 2 サイトで反可換にすると結論は破れる（可換になってしまう）
for M in [_sage_const_2 ,_sage_const_3 ]:
    xs = [SX]*M ; ys = [SZ]*M          # 全サイト反可換
    X = kron_list(xs); Y = kron_list(ys)
    # 反可換なサイトが偶数個なら XY = +YX（反交換子は 0 にならない）
    if M % _sage_const_2  == _sage_const_0 :
        rep.truth(np.max(np.abs(acomm(X,Y))) > _sage_const_1en6 ,
                  f"M={M}: 反可換サイトが偶数個だと [X,Y]+ != 0（仮定の必要性）")
rep.finish()

